:3,"w":1,"h":2,"color":"#e58fa0"}]},{"attachTo":"head","shapes":[{"type":"rect","x":4,"y":7,"w":1,"h":3,"color":"#2b1215"},{"type":"rect","x":11,"y":7,"w":1,"h":3,"color":"#2b1215"},{"type":"rect","x":6,"y":4,"w":4,"h":1,"color":"#2b1215"}]}]},"pivots":{"neck":[8,11],"shoulder":[8,13],"hip":[8,21]}},"collisionBox":{"w":12,"h":30},"stats":{"HP":15000,"AD":2000,"AP":3000,"ARM":1000,"MR":1500,"ARM_PEN":200,"MAGIC_PEN":300},"tags":["REGENERATION"],"behaviour":"walker","speed":150,"attack":{"damageType":"mixed","ratio":1.5,"attackTags":["ENERGY"],"range":120,"cooldown":1.5},"pattern":["charge","shoot","jump"],"phaseAt":0.4},"rooms":[{"id":"school-grounds","name":"Sugisawa High School Grounds","objective":"Cross the school grounds and get inside","layout":["......................................................................","......................................................................","......................................................................","......................................................................","......................................................................","......................................................................",".........................................2............................","......................................................................","..................................................1...........===.....",".......=====..................====..............=====......##.........","........................##.................................##.........","..S...........1.........##..^^......C...................3..##......E..","##################...#######################...#######################","##################...#######################...#######################"],"isBossRoom":false,"exit":{"toRoom":"haunted-corridors"}},{"id":"haunted-corridors","name":"Haunted Corridors","objective":"Follow the cursed energy up to the roof","layout":["########################################################################","........................................................................","........................................................................","........................................................................","........................................................2...............","........................................................................",".........................2.............................====.............","........................................................................","........................................................................",".......................======.....................====..................","..............#..................###.........................##.........","..S.......1...##..............^^.###..C....3.................##.1....E..","###################...########################..#######...##############","###################...########################..#######...##############"],"isBossRoom":false,"exit":{"toRoom":"the-rooftop"}},{"id":"the-rooftop","name":"The Rooftop","objective":"Defeat Sukuna","layout":["............................................","............................................","............................................","............................................","............................................","............................................","............................................","............................................","...........................====.............",".............====...........................","............................................","..S.....##.............^^........#.....B....","##################..########################","##################..########################"],"isBossRoom":true,"exit":{"toRoom":"END"}}],"dialogue":{"roomIntro":[[{"speaker":"Gojo","text":"A special grade cursed object loose at a high school at night. Sure, why not."},{"speaker":"Gojo","text":"Low-grade curses crawling everywhere. Relax, the strongest just showed up."}],[{"speaker":"Gojo","text":"These halls reek of cursed energy. Somebody swallowed something they really shouldn't have."},{"speaker":"Gojo","text":"Mind the floor. Curses love a building nobody's watching."}],[{"speaker":"Gojo","text":"Up on the roof? Let's see who's really in charge of that body."}]],"bossIntro":[{"speaker":"Sukuna","text":"So you're this era's strongest. Entertain me before the brat takes his body back."},{"speaker":"Gojo","text":"Ten seconds. If Yuji's still in there, he can come back after."}],"bossDefeated":[{"speaker":"Sukuna","text":"Tch. Enjoy it while it lasts, sorcerer."},{"speaker":"Gojo","text":"Welcome back, Yuji. You're going to need a lot of training."}],"playerDefeated":[{"speaker":"Sukuna","text":"The strongest? Don't make me laugh. Come back with a real technique."}]}},"notes":{"sourceFacts":["Yuji Itadori is a student at Sugisawa Third High School in Sendai.","Yuji swallows one of Ryomen Sukuna's fingers, a special grade cursed object, to fight off curses at his school at night.","Sukuna takes over Yuji's body; Gojo arrives and briefly fights Sukuna before Yuji regains control.","Gojo's technique is Limitless: Infinity stops attacks before they touch him; Blue pulls, Red repels, Hollow Purple combines both.","Gojo wears a black blindfold over his Six Eyes, has white hair and a dark high-collar jujutsu uniform.","When Sukuna takes over, extra eyes and black markings appear on Yuji's face."],"designChoices":["Gojo is played in his iconic form; Hollow Purple and teleport are shown later than episodes 1-2.","The three rooms (school grounds, corridors, rooftop) and the rooftop showdown are invented for the game.","Enemies are generic low-grade curses (crawler, floating eyeball, finger bearer), not specific named curses from episodes 1-2.","Sukuna is the boss; his attacks are mixed damage with ENERGY tags, so Gojo's Infinity makes him immune to them.","Sukuna gets REGENERATION to reflect his reverse cursed technique.","Every room is passable without abilities by the weakest demo character (Peppa), so any character can visit this world."]},"createdAt":"2026-11-21T12:00:00.000Z"}$$), '2026-11-21T12:00:00.000Z'::TIMESTAMP_TZ;

